/** Das Programm simuliert einen Staubsaugerroboter
 * @version 25.10.2016
 * @author Klaus Dingemann
 */
import sas.*;
import java.awt.Color;
class Staubsaugerroboter
{
   View view;
   Picture roboter;
   Circle[] staub;
   Rectangle teppich;
   Rectangle randlinks, randrechts, randoben, randunten;

   Staubsaugerroboter()
   {
      view = new View();
      view.setName("Staubsauger");
      this.erzeugeObjekte();
      this.fuehreAus();
   } 

   void erzeugeObjekte() {
      teppich = new Rectangle(0, 0, 600, 400, "teppich.jpg");
      randlinks = new Rectangle(0, 0, 20, 400, Color.BLUE);
      randoben = new Rectangle(0, 0, 600, 20, Color.BLUE);
      randrechts = new Rectangle(580, 0, 20, 400, Color.BLUE);
      randunten = new Rectangle(0, 380, 600, 200, Color.BLUE);

      staub = new Circle[300];
      for (int i = 0; i < 300; i++) {
         staub[i] = new Circle(Tools.randomNumber(25, 575), Tools.randomNumber(25, 375), 3, Color.YELLOW);
      } 
      roboter = new Picture(270, 170, "staubsauger.png");
     //und zufällig in eine Richtung gedreht
      roboter.setDirection(Tools.randomNumber(0, 360));
   }

   void saugeStaub() {
      for (int i = 0; i < 300; i++) {
         if (roboter.intersects(staub[i])) {
            view.remove(staub[i]);
         }
      }
   }

   void pruefeRand() {
      if (roboter.intersects(randlinks)) {
         roboter.setDirection(Tools.randomNumber(0, 180));
      }
      if (roboter.intersects(randrechts)) {
         roboter.setDirection(Tools.randomNumber(180, 360));
      }
      if (roboter.intersects(randoben)) {
         roboter.setDirection(Tools.randomNumber(90, 270));
      }
      if (roboter.intersects(randunten)) {
         roboter.setDirection(Tools.randomNumber(270, 450));
      }
   }

   void fuehreAus() { 
      while (!view.keyPressed('e')) {
         roboter.move(5);
         pruefeRand();
         saugeStaub();
         view.wait(10);
      }
   }

}

   Staubsaugerroboter robot = new Staubsaugerroboter();
      robot.fuehreAus();

/** Das Programm simuliert einen Staubsaugerroboter
 * @version 11.07.2016
 * @author Klaus Dingemann
 */
import sas.*;
import java.awt.Color;
class MuellSammeln
{
  View view;
  Sprite roboter;
  Rectangle teppich1;
  Rectangle teppich2;
  Rectangle teppich3;
  Rectangle teppich4;



  /**
   * Konstruktor für Objekte der Klasse MuellSammeln
   */
  MuellSammeln()
  {
    view = new View();
    view.setName("Staubsauger");
    this.erzeugeObjekte();
    this.fuehreAus();
  }   

  /** 
   * Erstellt und zeichnet das Roboter-Objekt als Sprite
   */ 
   void erzeugeObjekte(){
     teppich1 = new Rectangle(0, 300, 600, 60, Color.GREEN);
     teppich2 = new Rectangle(540, 0, 60, 360, Color.GREEN);
     teppich3 = new Rectangle(0, 0, 600, 60, Color.GREEN);
     teppich4 = new Rectangle(0, 0, 60, 360, Color.GREEN);
     roboter = new Sprite();
     roboter.add(new Circle(0, 300, 30, Color.RED));
     roboter.add(new Circle(20,320, 10, Color.BLUE));

   }



  /**
   * der Roboter entfernt die fünf Müllteile
   */
  void fuehreAus(){ 
      while(!view.keyPressed()){ view.wait(5);};
      //Das Programm startet, wenn eine Taste gedrückt wurde
      while (teppich1.contains(roboter)) {
        roboter.move(5,0);
        view.wait(50);
      }   
      roboter.move(-5,0);
      while (teppich2.contains(roboter)) {
        roboter.move(0,-5);
        view.wait(50);
      }   
      roboter.move(0,5);
      while (teppich3.contains(roboter)) {
        roboter.move(-5,0);
        view.wait(50);
      }   
      roboter.move(5,0);
      while (teppich4.contains(roboter)) {
        roboter.move(0,5);
        view.wait(50);
      }   
      roboter.move(0,-5);
  }
}
